<script setup lang="ts">
import { computed, nextTick, onMounted, ref } from "vue";
import { useRoute, useRouter } from "vue-router";
import { api, errorMessage, jsonRequest } from "@/api/client";
import type { LocationDetail as LocationDetailType, LocationSummary, ObservationRecord } from "@/api/types";
import LocationDetail from "@/components/locations/LocationDetail.vue";
import LocationForm from "@/components/locations/LocationForm.vue";

const route = useRoute(); const router = useRouter();
const items = ref<LocationSummary[]>([]); const query = ref(""); const type = ref("");
const loading = ref(true); const error = ref(""); const detailLoading = ref(false);
const detail = ref<LocationDetailType | null>(null); const dialog = ref<HTMLDialogElement>();
const formDialog = ref<HTMLDialogElement>(); const formOpen = ref(false); const editing = ref<LocationDetailType | null>(null);
const linkDialog = ref<HTMLDialogElement>(); const linkOpen = ref(false); const observations = ref<ObservationRecord[]>([]); const linkedIds = ref<number[]>([]); const linkStatus = ref("");
const coverInput = ref<HTMLInputElement>();
const locationTypes: Record<string, string> = { wetland_park: "湿地公园", forest_park: "森林公园", urban_park: "城市公园", nature_reserve: "自然保护区", reservoir: "水库", farmland: "农田", coast: "海岸", other: "其他" };
const filtered = computed(() => { const needle = query.value.trim().toLocaleLowerCase(); return items.value.filter((item) => `${item.name} ${item.admin1_name} ${item.city || ""} ${item.district || ""}`.toLocaleLowerCase().includes(needle) && (!type.value || item.location_type === type.value)); });
const countLabel = computed(() => query.value || type.value ? `${filtered.value.length}/${items.value.length}` : items.value.length);

async function load(): Promise<void> { loading.value = true; error.value = ""; try { items.value = await api<LocationSummary[]>("/api/locations"); } catch (caught) { error.value = errorMessage(caught); } finally { loading.value = false; } }
async function open(id: number): Promise<void> { detailLoading.value = true; detail.value = null; await nextTick(); if (!dialog.value?.open) dialog.value?.showModal(); try { detail.value = await api<LocationDetailType>(`/api/locations/${id}`); const query = { ...route.query }; delete query.new; await router.replace({ query: { ...query, location: String(id) } }); } catch (caught) { error.value = errorMessage(caught); dialog.value?.close(); } finally { detailLoading.value = false; } }
function close(): void { dialog.value?.close(); detail.value = null; const next = { ...route.query }; delete next.location; void router.replace({ query: next }); }
async function openForm(location: LocationDetailType | null = null): Promise<void> { editing.value = location; formOpen.value = true; await nextTick(); formDialog.value?.showModal(); }
function hideForm(): void { formDialog.value?.close(); formOpen.value = false; editing.value = null; }
function closeForm(): void { hideForm(); if (route.query.new) { const query = { ...route.query }; delete query.new; void router.replace({ query }); } }
async function formSaved(saved: LocationDetailType): Promise<void> { hideForm(); await load(); await open(saved.id); }
async function openLink(): Promise<void> { if (!detail.value) return; linkStatus.value = "正在读取观察记录…"; linkOpen.value = true; await nextTick(); linkDialog.value?.showModal(); try { observations.value = await api<ObservationRecord[]>("/api/observations"); linkedIds.value = observations.value.filter((item) => item.location?.id === detail.value?.id).map((item) => item.id); linkStatus.value = ""; } catch (caught) { linkStatus.value = errorMessage(caught); } }
function closeLink(): void { linkDialog.value?.close(); linkOpen.value = false; }
async function saveLinks(): Promise<void> { if (!detail.value) return; linkStatus.value = "正在保存关联…"; try { await api(`/api/locations/${detail.value.id}/observations`, jsonRequest("PUT", { observation_ids: linkedIds.value })); closeLink(); await load(); await open(detail.value.id); } catch (caught) { linkStatus.value = errorMessage(caught); } }
function chooseCover(): void { coverInput.value?.click(); }
async function uploadCover(event: Event): Promise<void> { if (!detail.value) return; const input = event.target as HTMLInputElement; const file = input.files?.[0]; if (!file) return; const body = new FormData(); body.append("photo", file); try { await api(`/api/locations/${detail.value.id}/cover`, { method: "POST", body }); input.value = ""; await load(); await open(detail.value.id); } catch (caught) { error.value = errorMessage(caught); input.value = ""; } }
async function remove(): Promise<void> { if (!detail.value || !confirm("删除区域只会解除观察关联，不会删除任何观察记录。确定删除吗？")) return; try { await api(`/api/locations/${detail.value.id}`, { method: "DELETE" }); close(); await load(); } catch (caught) { error.value = errorMessage(caught); } }
onMounted(async () => { await load(); const requested = Number(route.query.location); if (requested && items.value.some((item) => item.id === requested)) await open(requested); else if (route.query.new === "1") await openForm(); });
</script>

<template>
  <main class="v2-archive-layout"><aside class="v2-archive-sidebar"><div class="v2-book-tab">REGION FILES</div><p class="v2-kicker">调查据点目录</p><h1>区域档案</h1><p class="v2-filter-intro">把反复到访的校园、湿地与森林整理为独立调查区域，观察它们随时间积累的物种情报。</p><label class="v2-search-label" for="vue-location-search">检索区域</label><input id="vue-location-search" v-model="query" class="v2-search" type="search" placeholder="地点、城市或行政区" /><label for="vue-location-type">区域类型</label><select id="vue-location-type" v-model="type"><option value="">全部类型</option><option v-for="(label, value) in locationTypes" :key="value" :value="value">{{ label }}</option></select><button class="v2-filter-reset" type="button" @click="query = ''; type = ''">清除检索条件</button><RouterLink class="v2-filter-reset" to="/map">打开跨区域地图总览</RouterLink><div class="v2-book-count"><strong>{{ countLabel }}</strong><span>份区域档案</span></div></aside>
    <section class="v2-archive-content"><header class="v2-dex-header"><div><p class="v2-kicker">探索区域</p><h2>曾经停留的自然据点</h2></div><button class="v2-new-entry" type="button" @click="openForm()">＋ 建立区域</button></header><p v-if="loading" class="v2-loading">正在展开区域地图…</p><p v-else-if="error" class="v2-loading">{{ error }}</p><div v-else class="v2-location-grid"><button v-for="item in filtered" :key="item.id" class="v2-region-card" type="button" @click="open(item.id)"><span class="v2-region-photo"><img v-if="item.cover_url" :src="item.cover_url" :alt="item.name" loading="lazy" /><i v-else>⌖</i><b>{{ item.catalog_number }}</b></span><span class="v2-region-copy"><small>{{ locationTypes[item.location_type] || item.location_type }}</small><strong>{{ item.name }}</strong><em>{{ item.admin1_name }} · {{ item.city || item.district || "" }}</em><span class="v2-card-stat-grid"><article><strong>{{ item.species_count }}</strong><span>物种</span></article><article><strong>{{ item.observation_count }}</strong><span>记录</span></article><article><strong>{{ item.visit_day_count }}</strong><span>到访日</span></article></span></span></button></div><div v-if="!loading && !error && !filtered.length" class="v2-empty"><strong>没有找到对应区域</strong><span>换一个名称或区域类型试试。</span></div></section></main>
  <dialog ref="dialog" class="v2-archive-dialog" @click.self="close"><p v-if="detailLoading" class="v2-loading v2-dossier-loading">正在调取区域档案…</p><LocationDetail v-if="detail" :detail="detail" @close="close" @edit="openForm(detail)" @cover="chooseCover" @link="openLink" @delete="remove" /></dialog>
  <dialog ref="formDialog" class="record-dialog location-form-dialog" @click.self="closeForm"><LocationForm v-if="formOpen" :location="editing" @close="closeForm" @saved="formSaved" /></dialog>
  <dialog ref="linkDialog" class="record-dialog location-link-dialog" @click.self="closeLink"><form v-if="linkOpen" @submit.prevent="saveLinks"><header class="dialog-header"><div><p class="eyebrow">LINK RECORDS</p><h2>关联已有观察</h2></div><button type="button" class="icon-button" aria-label="关闭" @click="closeLink">×</button></header><div class="form-scroll"><p class="section-note">勾选属于当前地点的记录。已属于其他地点的记录被勾选后将移动到这里。</p><div class="location-link-list"><label v-for="item in observations" :key="item.id" class="location-link-item"><input v-model="linkedIds" type="checkbox" :value="item.id" /><img :src="item.thumbnail_url" alt="" /><span><strong>{{ item.species_name }}</strong><small>{{ item.observed_at.replace('T', ' ') }} · {{ item.locality }}</small><em v-if="item.location && item.location.id !== detail?.id">当前：{{ item.location.name }}</em></span></label><p v-if="!observations.length" class="compact-empty">尚无可关联的观察记录。</p></div></div><footer class="dialog-footer"><span role="status">{{ linkStatus }}</span><button type="submit" class="primary-button">保存关联</button></footer></form></dialog>
  <input ref="coverInput" type="file" accept="image/jpeg,.jpg,.jpeg" hidden @change="uploadCover" />
</template>
